package com.labmaker.app;
import org.junit.Test;import static org.junit.Assert.*;
import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
public class ResourceIntegrityTest {
 private String hash(byte[] data)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))out.append(String.format("%02x",b&255));return out.toString();}
 private JSONObject manifest(Map<String,byte[]> files)throws Exception{JSONArray rows=new JSONArray();for(Map.Entry<String,byte[]> f:files.entrySet())rows.put(new JSONObject().put("path",f.getKey()).put("bytes",f.getValue().length).put("sha256",hash(f.getValue())));return new JSONObject().put("schema",1).put("files",rows);}
 @Test public void checksEveryResourceAndStreamsAccurateProgress()throws Exception{Map<String,byte[]> data=new LinkedHashMap<>();data.put("assets/report.zip",new byte[150000]);data.put("lib/arm64-v8a/ocr.so",new byte[]{1,2,3});AtomicInteger progress=new AtomicInteger();JSONObject r=ResourceIntegrity.check(manifest(data),p->new ByteArrayInputStream(data.get(p)),new AtomicBoolean(),(checked,total,bytes,path)->{assertEquals(2,total);progress.incrementAndGet();});assertTrue(r.getBoolean("complete"));assertEquals(2,r.getInt("checked"));assertEquals(150003,r.getLong("bytes"));assertEquals(2,progress.get());}
 @Test public void missingWrongSizeHashAndReadFailuresAreAllReported()throws Exception{Map<String,byte[]> expected=new LinkedHashMap<>();for(String n:new String[]{"missing","size","hash","read"})expected.put("assets/"+n,new byte[]{1,2,3});JSONObject r=ResourceIntegrity.check(manifest(expected),p->{if(p.endsWith("missing"))throw new FileNotFoundException();if(p.endsWith("read"))throw new IOException();return new ByteArrayInputStream(p.endsWith("size")?new byte[]{1}:new byte[]{4,5,6});},new AtomicBoolean(),(a,b,c,d)->{});assertFalse(r.getBoolean("complete"));assertEquals(4,r.getJSONArray("problems").length());Set<String> reasons=new HashSet<>();for(int i=0;i<4;i++)reasons.add(r.getJSONArray("problems").getJSONObject(i).getString("reason"));assertEquals(new HashSet<>(Arrays.asList("缺失","长度不符","校验不符","读取失败")),reasons);}
 @Test public void cancelledStreamIsClosedAndCannotReportComplete()throws Exception{AtomicBoolean cancel=new AtomicBoolean(),closed=new AtomicBoolean();Map<String,byte[]> data=Collections.singletonMap("assets/large.bin",new byte[200000]);JSONObject r=ResourceIntegrity.check(manifest(data),p->new ByteArrayInputStream(data.get(p)){@Override public synchronized int read(byte[] b,int off,int len){int n=super.read(b,off,len);cancel.set(true);return n;}@Override public void close(){closed.set(true);}},cancel,(a,b,c,d)->{});assertTrue(r.getBoolean("cancelled"));assertFalse(r.getBoolean("complete"));assertTrue(closed.get());assertEquals(0,r.getInt("checked"));}
 @Test public void malformedDuplicateAndEmptyInventoriesNeverPass()throws Exception{JSONObject valid=manifest(Collections.singletonMap("assets/a",new byte[]{1}));valid.getJSONArray("files").put(valid.getJSONArray("files").getJSONObject(0));assertThrows(Exception.class,()->ResourceIntegrity.check(valid,p->null,new AtomicBoolean(),(a,b,c,d)->{}));JSONObject bad=manifest(Collections.singletonMap("assets/../private",new byte[]{1}));assertThrows(Exception.class,()->ResourceIntegrity.check(bad,p->null,new AtomicBoolean(),(a,b,c,d)->{}));assertThrows(Exception.class,()->ResourceIntegrity.check(new JSONObject().put("schema",1).put("files",new JSONArray()),p->null,new AtomicBoolean(),(a,b,c,d)->{}));}
}
